312	<script>
313	(() => {
314	  const stage = document.getElementById("stage");
315	  const photo = document.getElementById("photo");
316	  const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
317	  const mm = v => new THREE.Vector3(v[0] / 1000, v[1] / 1000, v[2] / 1000);
318	  const V = (x, y, z) => new THREE.Vector3(x, y, z);
319	  if (!window.THREE) { stage.insertAdjacentHTML("beforeend", "<p style='position:absolute;padding:16px'>The 3D library did not load. Check your connection and reload the page.</p>"); return; }
320	
321	  const state = { comp: "susp", view: "model", playSusp: true, auto: true, outline: false, pedal: 0.3 };
322	  const WB = 3.29, GROUND = -WHEEL_R / 1000;
323	
324	  // ---------- renderer, cameras ----------
325	  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
326	  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
327	  stage.insertBefore(renderer.domElement, document.getElementById("hint"));
328	  const scene = new THREE.Scene();
329	  const cam = new THREE.PerspectiveCamera(32, 1200 / 803, 0.05, 60);
330	  cam.up.set(0, 0, 1);
331	  const controls = new THREE.OrbitControls(cam, renderer.domElement);
332	  controls.enableDamping = true; controls.minDistance = 0.8; controls.maxDistance = 16;
333	  const VIEWS = {
334	    susp: { pos: [2.0, 2.5, 0.75], target: [-0.3, 0.25, -0.12] },
335	    blower: { pos: [1.35, 0.75, 1.05], target: [-0.38, 0.02, 0.28] },
336	  };
337	  // Camera fitted to the museum photo from wheel, tyre, mascot, windscreen and bumper correspondences.
338	  const PHOTO_CAM = { c: [3037.2, 3487.3, 1696.0], yaw: -2.4279, pitch: -0.2495, roll: -0.0171, f: 1320.9 };
339	  const photoCam = new THREE.PerspectiveCamera(2 * Math.atan(401.5 / PHOTO_CAM.f) * 180 / Math.PI, 1200 / 803, 0.05, 60);
340	  function aimPhotoCam() {
341	    const { yaw, pitch, roll } = PHOTO_CAM;
342	    const f = V(Math.cos(pitch) * Math.cos(yaw), Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch));
343	    const r = new THREE.Vector3().crossVectors(f, V(0, 0, 1)).normalize();
344	    const u = new THREE.Vector3().crossVectors(r, f);
345	    photoCam.position.copy(mm(PHOTO_CAM.c));
346	    photoCam.up.copy(u.clone().multiplyScalar(Math.cos(roll)).addScaledVector(r, -Math.sin(roll)));
347	    photoCam.lookAt(photoCam.position.clone().add(f));
348	    photoCam.fov = 2 * Math.atan(401.5 / PHOTO_CAM.f) * 180 / Math.PI; photoCam.updateProjectionMatrix();
349	  }
350	  aimPhotoCam();
351	  scene.add(new THREE.HemisphereLight(0xffffff, 0x445566, 0.95));
352	  const sun = new THREE.DirectionalLight(0xffffff, 0.65); sun.position.set(3, 4, 6); scene.add(sun);
353	
354	  // ---------- helpers ----------
355	  const mat = (c = 0xffffff, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.5, metalness: 0.15, ...o });
356	  const metal = mat(), dark = mat(0x343b42);
357	  const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 16), sphGeo = new THREE.SphereGeometry(1, 16, 12);
358	  const Y = V(0, 1, 0);
359	  function rod(m, r) { const o = new THREE.Mesh(cylGeo, m); o.userData.r = r; return o; }
360	  function place(o, a, b) {
361	    const d = new THREE.Vector3().subVectors(b, a), len = d.length();

679	  function applyColors() {
680	    paintRoad();
681	    metal.color.set(css("--metal")); springMat.color.set(css("--l4"));
682	    LINKS.forEach((L, i) => linkMats[i].color.set(css(L.tok)));
683	    colBypass.set(css("--l4")); colBoost.set(css("--l1")); plateMat.color.set(css("--l1"));
684	    const onPhoto = state.view === "photo";
685	    const line = onPhoto ? "#ffffff" : css("--fg");
686	    edgeMat.color.set(line); ghostMat.color.set(line);
687	    scene.background = onPhoto ? null : new THREE.Color(css("--stage"));
688	  }
689	  const legend = document.getElementById("legend");
690	  legend.innerHTML = [["--l1", "Lower wishbone (two legs)"], ["--l2", "Upper wishbone (two legs)"], ["--l5", "Track rod"], ["--l4", "Coil spring"], ["--metal", "Frame and knuckle"]]
691	    .map(([t, n]) => `<li><span class="sw" style="background:var(${t})"></span>${n}</li>`).join("");
692	
693	  // ---------- trace ----------
694	  const traceSvg = document.getElementById("trace"), trace = [];
695	  const TW = 280, TSPAN = 6;
696	  traceSvg.innerHTML = `<line x1="0" y1="55" x2="${TW}" y2="55" stroke="var(--rule)"/><line x1="0" y1="5" x2="${TW}" y2="5" stroke="var(--rule)" stroke-dasharray="2 3"/><line x1="0" y1="105" x2="${TW}" y2="105" stroke="var(--rule)" stroke-dasharray="2 3"/>
697	    <polyline id="tTravel" fill="none" stroke="var(--accent)" stroke-width="1.6"/><polyline id="tLoad" fill="none" stroke="var(--l1)" stroke-width="1.6"/>
698	    <text x="${TW - 2}" y="15" text-anchor="end">bump / 200 %</text><text x="${TW - 2}" y="101" text-anchor="end">rebound / 0 %</text>`;
699	  const tTravel = traceSvg.querySelector("#tTravel"), tLoad = traceSvg.querySelector("#tLoad");
700	  function drawTrace(t) {
701	    while (trace.length && trace[0].t < t - TSPAN) trace.shift();
702	    const X = tt => ((tt - (t - TSPAN)) / TSPAN * TW).toFixed(1);
703	    tTravel.setAttribute("points", trace.map(p => `${X(p.t)},${(55 - Math.max(-60, Math.min(60, p.travel)) / 60 * 50).toFixed(1)}`).join(" "));
704	    tLoad.setAttribute("points", trace.map(p => `${X(p.t)},${(105 - Math.min(200, p.load) / 200 * 100).toFixed(1)}`).join(" "));
705	  }
706	
707	  // ---------- simulation ----------
708	  const SPEED = 25 / 3.6, SLOWMO = 0.2, DT = 0.0005;
709	  const front = corner(), rear = corner();
710	  let dist = 0, simT = 0, photoT = 0, autoT = 0;
711	  function stepRoad(realDt) {
712	    let h = Math.min(realDt, 0.05) * SLOWMO;
713	    while (h > 1e-9) {
714	      const dt = Math.min(DT, h); h -= dt; simT += dt; dist += SPEED * dt;
715	      stepCorner(front, roadProfile(dist), dt);
716	      stepCorner(rear, roadProfile(dist - WB), dt);
717	    }
718	  }
719	  // Auto demo pedal: cruise, part throttle, floor it (blower in), lift off.
720	  function autoPedal(t) {
721	    t %= 10;
722	    if (t < 2) return 0.25 + 0.5 * t / 2;
723	    if (t < 3.5) return 0.75;
724	    if (t < 3.8) return 0.75 + 0.25 * (t - 3.5) / 0.3;
725	    if (t < 7.5) return 1;
726	    if (t < 8) return 1 - 0.75 * (t - 7.5) / 0.5;
727	    return 0.25;
