  function applyColors() {
    paintRoad();
    metal.color.set(css("--metal")); springMat.color.set(css("--l4"));
    LINKS.forEach((L, i) => linkMats[i].color.set(css(L.tok)));
    colBypass.set(css("--l4")); colBoost.set(css("--l1")); plateMat.color.set(css("--l1"));
    const onPhoto = state.view === "photo";
    const line = onPhoto ? "#ffffff" : css("--fg");
    edgeMat.color.set(line); ghostMat.color.set(line);
    scene.background = onPhoto ? null : new THREE.Color(css("--stage"));
  }
  const legend = document.getElementById("legend");
  legend.innerHTML = [["--l1", "Lower wishbone (two legs)"], ["--l2", "Upper wishbone (two legs)"], ["--l5", "Track rod"], ["--l4", "Coil spring"], ["--metal", "Frame and knuckle"]]
    .map(([t, n]) => `<li><span class="sw" style="background:var(${t})"></span>${n}</li>`).join("");

  // ---------- trace ----------
  const traceSvg = document.getElementById("trace"), trace = [];
  const TW = 280, TSPAN = 6;
  traceSvg.innerHTML = `<line x1="0" y1="55" x2="${TW}" y2="55" stroke="var(--rule)"/><line x1="0" y1="5" x2="${TW}" y2="5" stroke="var(--rule)" stroke-dasharray="2 3"/><line x1="0" y1="105" x2="${TW}" y2="105" stroke="var(--rule)" stroke-dasharray="2 3"/>
    <polyline id="tTravel" fill="none" stroke="var(--accent)" stroke-width="1.6"/><polyline id="tLoad" fill="none" stroke="var(--l1)" stroke-width="1.6"/>
    <text x="${TW - 2}" y="15" text-anchor="end">bump / 200 %</text><text x="${TW - 2}" y="101" text-anchor="end">rebound / 0 %</text>`;
  const tTravel = traceSvg.querySelector("#tTravel"), tLoad = traceSvg.querySelector("#tLoad");
  function drawTrace(t) {
    while (trace.length && trace[0].t < t - TSPAN) trace.shift();
    const X = tt => ((tt - (t - TSPAN)) / TSPAN * TW).toFixed(1);
    tTravel.setAttribute("points", trace.map(p => `${X(p.t)},${(55 - Math.max(-60, Math.min(60, p.travel)) / 60 * 50).toFixed(1)}`).join(" "));
    tLoad.setAttribute("points", trace.map(p => `${X(p.t)},${(105 - Math.min(200, p.load) / 200 * 100).toFixed(1)}`).join(" "));
  }

  // ---------- simulation ----------
  const SPEED = 25 / 3.6, SLOWMO = 0.2, DT = 0.0005;
  const front = corner(), rear = corner();
  let dist = 0, simT = 0, photoT = 0, autoT = 0;
  function stepRoad(realDt) {
    let h = Math.min(realDt, 0.05) * SLOWMO;
    while (h > 1e-9) {
      const dt = Math.min(DT, h); h -= dt; simT += dt; dist += SPEED * dt;
      stepCorner(front, roadProfile(dist), dt);
      stepCorner(rear, roadProfile(dist - WB), dt);
    }
  }
  // Auto demo pedal: cruise, part throttle, floor it (blower in), lift off.
  function autoPedal(t) {
    t %= 10;
    if (t < 2) return 0.25 + 0.5 * t / 2;
    if (t < 3.5) return 0.75;
    if (t < 3.8) return 0.75 + 0.25 * (t - 3.5) / 0.3;
    if (t < 7.5) return 1;
    if (t < 8) return 1 - 0.75 * (t - 7.5) / 0.5;
    return 0.25;
  }

  // ---------- UI wiring ----------
  const $ = id => document.getElementById(id);
  function setSeg(id, v) { $(id).querySelectorAll("button").forEach(b => b.setAttribute("aria-pressed", String(b.dataset.v === v))); }
  function refreshLayout() {
    const onPhoto = state.view === "photo", isSusp = state.comp === "susp";
    document.querySelectorAll("[data-comp]").forEach(el => el.hidden = el.dataset.comp !== state.comp);
    document.querySelectorAll("[data-only]").forEach(el => el.hidden = (el.dataset.only === "photo") !== onPhoto);
    photo.hidden = !onPhoto; $("credit").hidden = !onPhoto; $("hint").hidden = onPhoto;
    controls.enabled = !onPhoto;
    susp.visible = isSusp; blower.visible = !isSusp;
    world.visible = !onPhoto && isSusp;
    ghost.visible = onPhoto ? state.outline : isSusp;
    ghostMat.opacity = onPhoto ? 0.0 : (isSusp ? 0.06 : 0.035);
    edgeMat.opacity = onPhoto ? 0.7 : (isSusp ? 0.5 : 0.25);
    frontTyreMat.opacity = onPhoto ? 0.0 : 0.5;
    spokeMat.opacity = onPhoto ? 0.0 : 0.8; spokeMat.userData.solid.visible = !onPhoto;
    document.querySelectorAll(".outlineBtn").forEach(b => b.setAttribute("aria-pressed", String(state.outline)));
    if (!onPhoto) { const v = VIEWS[state.comp]; cam.position.set(...v.pos); controls.target.set(...v.target); controls.update(); }
    applyColors();
  }
  $("segComp").addEventListener("click", e => { const v = e.target.closest("button")?.dataset.v; if (v) { state.comp = v; setSeg("segComp", v); refreshLayout(); } });
  $("segView").addEventListener("click", e => { const v = e.target.closest("button")?.dataset.v; if (v) { state.view = v; setSeg("segView", v); refreshLayout(); } });
  $("playSusp").addEventListener("click", () => { state.playSusp = !state.playSusp; $("playSusp").setAttribute("aria-pressed", String(state.playSusp)); $("playSusp").textContent = state.playSusp ? "Pause" : "Play"; });
  function setAuto(on) { state.auto = on; $("autoDemo").setAttribute("aria-pressed", String(on)); $("autoDemo").textContent = on ? "Auto demo on" : "Auto demo off"; }
  $("autoDemo").addEventListener("click", () => { setAuto(!state.auto); autoT = 0; });
  $("throttle").addEventListener("input", e => { setAuto(false); state.pedal = +e.target.value / 100; });
  $("floorIt").addEventListener("click", () => { setAuto(false); state.pedal = 1; $("throttle").value = 100; });
  document.querySelectorAll(".outlineBtn").forEach(b => b.addEventListener("click", () => { state.outline = !state.outline; refreshLayout(); }));

  function resize() { const w = stage.clientWidth, h = stage.clientHeight; renderer.setSize(w, h, false); cam.aspect = w / h; cam.updateProjectionMatrix(); }
  new ResizeObserver(resize).observe(stage);
  matchMedia("(prefers-color-scheme: dark)").addEventListener("change", applyColors);
  new MutationObserver(applyColors).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) { state.playSusp = false; $("playSusp").setAttribute("aria-pressed", "false"); $("playSusp").textContent = "Play"; setAuto(false); }

  // ---------- frame ----------
  let last = performance.now(), frame = 0;
  function frameUpdate(now) {
    const dt = Math.min((now - last) / 1000, 0.05); last = now; frame++;
    const onPhoto = state.view === "photo";
    if (state.comp === "susp") {
      let travel, load = 100;
      if (onPhoto) {
        if (state.playSusp) photoT += dt;
        travel = Math.sin(photoT * 1.4) * 60;
        car.position.set(0, 0, 0); car.rotation.set(0, 0, 0);
      } else {
        if (state.playSusp) stepRoad(dt);
        travel = Math.max(-80, Math.min(80, (front.zu - front.zs) * 1000));
        load = front.load / QC.fStatic * 100;
        car.position.set(0, 0, front.zs);
        car.rotation.set(0, Math.asin((rear.zs - front.zs) / WB), 0);
        updateRoad(dist);
        rearWheels.forEach(w => w.position.z = rear.zu);
        [[front, 0], [front, 1], [rear, 2], [rear, 3]].forEach(([c, i]) => {
          const p = patches[i], ratio = Math.max(0, c.load / QC.fStatic);
          p.position.z = GROUND + c.zr + 0.002;
          p.scale.set(0.02 + 0.075 * ratio, 0.07, 1);
          p.material.color.set(css(ratio < 0.35 ? "--warn" : "--l1"));
          p.material.opacity = ratio < 0.02 ? 0.25 : 0.9;
        });
        if (state.playSusp) { trace.push({ t: simT, travel, load }); if (frame % 2 === 0) drawTrace(simT); }
      }
      const a = poseSusp(travel);
      $("oTravel").value = travel.toFixed(0); $("oCamber").value = a.camber.toFixed(2); $("oTrack").value = a.track.toFixed(1);
      $("oLoad").value = onPhoto ? "–" : load.toFixed(0);
    } else {
      car.position.set(0, 0, 0); car.rotation.set(0, 0, 0);
      if (state.auto) { autoT += dt; state.pedal = autoPedal(autoT); $("throttle").value = Math.round(state.pedal * 100); }
      poseBlower(dt);
      if (frame % 2 === 0) drawRotorSvg();
      $("oPedal").value = Math.round(state.pedal * 100);
      $("oRotor").value = (BLOWER.ratio * bstate.spin).toFixed(1);
      $("oBoost").value = bstate.boost.toFixed(2);
      $("oPower").value = Math.round(bstate.power);
      const badge = $("clutchBadge"); badge.textContent = bstate.engaged ? "Clutch engaged" : "Clutch open"; badge.classList.toggle("on", bstate.engaged);
      $("boostMeter").firstElementChild.style.width = (bstate.boost / BLOWER.boostMax * 100).toFixed(0) + "%";
      $("boostMeter").classList.toggle("hot", bstate.spin > 0.5);
    }
  }

  applyColors(); resize(); refreshLayout(); poseBlower(0); drawRotorSvg();
  window.__k = { PHOTO_CAM, aimPhotoCam, state, refreshLayout };
  (function loop(now) {
    requestAnimationFrame(loop);
    frameUpdate(now);
    if (state.view === "model") controls.update();
    renderer.render(scene, state.view === "photo" ? photoCam : cam);
  })(performance.now());
})();
</script>

