{
  const s = new THREE.Shape();
  s.moveTo(-990, -130); s.lineTo(-360, -130); s.lineTo(-360, 0); s.absarc(0, 0, 360, Math.PI, 0, true);
  s.lineTo(360, -130); s.lineTo(2665 - 360, -130); s.lineTo(2665 - 360, 0); s.absarc(2665, 0, 360, Math.PI, 0, true);
  s.lineTo(3025, -130); s.lineTo(3400, -130); s.lineTo(3435, 210); s.lineTo(3390, 470); s.lineTo(1980, 565);
  s.lineTo(-560, 615); s.lineTo(-985, 600); s.lineTo(-1015, 360); s.lineTo(-990, -130);
  const lower = new THREE.ExtrudeGeometry(s, { depth: 1678, bevelEnabled: false, curveSegments: 18 });
  lower.rotateX(Math.PI / 2); lower.translate(0, 839, 0); lower.scale(0.001, 0.001, 0.001);
  const gh = new THREE.Shape();
  gh.moveTo(1980, 565); gh.lineTo(1320, 1098); gh.lineTo(140, 1098); gh.lineTo(-560, 615); gh.lineTo(1980, 565);
  const upper = new THREE.ExtrudeGeometry(gh, { depth: 1380, bevelEnabled: false });
  upper.rotateX(Math.PI / 2); upper.translate(0, 690, 0); upper.scale(0.001, 0.001, 0.001);
  for (const g of [lower, upper]) { ghost.add(new THREE.Mesh(g, ghostMat)); ghost.add(new THREE.LineSegments(new THREE.EdgesGeometry(g, 20), edgeMat)); }

