214	function rotm(v) {
215	  const th = Math.hypot(v[0], v[1], v[2]);
216	  if (th < 1e-12) return [1, 0, 0, 0, 1, 0, 0, 0, 1];
217	  const x = v[0] / th, y = v[1] / th, z = v[2] / th, c = Math.cos(th), s = Math.sin(th), C = 1 - c;
218	  return [c + x * x * C, x * y * C - z * s, x * z * C + y * s,
219	          y * x * C + z * s, c + y * y * C, y * z * C - x * s,
220	          z * x * C - y * s, z * y * C + x * s, c + z * z * C];
221	}
222	const mul = (R, v) => [R[0] * v[0] + R[1] * v[1] + R[2] * v[2], R[3] * v[0] + R[4] * v[1] + R[5] * v[2], R[6] * v[0] + R[7] * v[1] + R[8] * v[2]];
223	function carrierPoint(q, local, R = rotm(q.slice(3))) {
224	  const p = mul(R, local);
225	  return [p[0] + q[0] + W0[0], p[1] + q[1] + W0[1], p[2] + q[2] + W0[2]];
226	}
227	function residual(q, s) {
228	  const R = rotm(q.slice(3));
229	  const r = LINKS.map(L => {
230	    const p = carrierPoint(q, L.cl, R);
231	    const d = [p[0] - L.b[0], p[1] - L.b[1], p[2] - L.b[2]];
232	    return (d[0] * d[0] + d[1] * d[1] + d[2] * d[2] - L.len2) / 1000;
233	  });
234	  r.push(q[2] - s);
235	  return r;
236	}
237	function gauss(A, b) {
238	  const n = b.length, M = A.map((row, i) => [...row, b[i]]);
239	  for (let k = 0; k < n; k++) {
240	    let p = k;
241	    for (let i = k + 1; i < n; i++) if (Math.abs(M[i][k]) > Math.abs(M[p][k])) p = i;
242	    [M[k], M[p]] = [M[p], M[k]];
243	    for (let i = k + 1; i < n; i++) {
244	      const f = M[i][k] / M[k][k];
245	      for (let j = k; j <= n; j++) M[i][j] -= f * M[k][j];
246	    }
247	  }
248	  const x = new Array(n).fill(0);
249	  for (let i = n - 1; i >= 0; i--) {
250	    let s = M[i][n];
251	    for (let j = i + 1; j < n; j++) s -= M[i][j] * x[j];
252	    x[i] = s / M[i][i];
253	  }
254	  return x;
255	}
256	function solve(q0, s) {
257	  const q = q0.slice();
258	  for (let it = 0; it < 30; it++) {
259	    const r = residual(q, s);
260	    if (Math.max(...r.map(Math.abs)) < 1e-10) break;
261	    const J = r.map(() => new Array(6));
262	    for (let j = 0; j < 6; j++) {
263	      const h = j < 3 ? 1e-4 : 1e-7, qh = q.slice();
264	      qh[j] += h;
265	      const rh = residual(qh, s);
266	      for (let i = 0; i < 6; i++) J[i][j] = (rh[i] - r[i]) / h;
267	    }
268	    const dq = gauss(J, r.map(v => -v));
269	    for (let j = 0; j < 6; j++) q[j] += dq[j];
270	  }
271	  return q;
272	}
273	// Camber: negative = top of wheel inboard. Track change: sideways shift of the contact point, + = outward.
274	function angles(q) {
275	  const R = rotm(q.slice(3)), a = mul(R, [0, 1, 0]);
276	  return { camber: -Math.atan2(a[2], a[1]) * 180 / Math.PI, track: carrierPoint(q, [0, 0, -WHEEL_R], R)[1] - W0[1] };
277	}
278	// SOLVER END
