function rotm(v) {
  const th = Math.hypot(v[0], v[1], v[2]);
  if (th < 1e-12) return [1, 0, 0, 0, 1, 0, 0, 0, 1];
  const x = v[0] / th, y = v[1] / th, z = v[2] / th, c = Math.cos(th), s = Math.sin(th), C = 1 - c;
  return [c + x * x * C, x * y * C - z * s, x * z * C + y * s,
          y * x * C + z * s, c + y * y * C, y * z * C - x * s,
          z * x * C - y * s, z * y * C + x * s, c + z * z * C];
}
const mul = (R, v) => [R[0] * v[0] + R[1] * v[1] + R[2] * v[2], R[3] * v[0] + R[4] * v[1] + R[5] * v[2], R[6] * v[0] + R[7] * v[1] + R[8] * v[2]];
function carrierPoint(q, local, R = rotm(q.slice(3))) {
  const p = mul(R, local);
  return [p[0] + q[0] + W0[0], p[1] + q[1] + W0[1], p[2] + q[2] + W0[2]];
}
function residual(q, s) {
  const R = rotm(q.slice(3));
  const r = LINKS.map(L => {
    const p = carrierPoint(q, L.cl, R);
    const d = [p[0] - L.b[0], p[1] - L.b[1], p[2] - L.b[2]];
    return (d[0] * d[0] + d[1] * d[1] + d[2] * d[2] - L.len2) / 1000;
  });
  r.push(q[2] - s);
  return r;
}
function gauss(A, b) {
  const n = b.length, M = A.map((row, i) => [...row, b[i]]);
  for (let k = 0; k < n; k++) {
    let p = k;
    for (let i = k + 1; i < n; i++) if (Math.abs(M[i][k]) > Math.abs(M[p][k])) p = i;
    [M[k], M[p]] = [M[p], M[k]];
    for (let i = k + 1; i < n; i++) {
      const f = M[i][k] / M[k][k];
      for (let j = k; j <= n; j++) M[i][j] -= f * M[k][j];
    }
  }
  const x = new Array(n).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    let s = M[i][n];
    for (let j = i + 1; j < n; j++) s -= M[i][j] * x[j];
    x[i] = s / M[i][i];
  }
  return x;
}
function solve(q0, s) {
  const q = q0.slice();
  for (let it = 0; it < 30; it++) {
    const r = residual(q, s);
    if (Math.max(...r.map(Math.abs)) < 1e-10) break;
    const J = r.map(() => new Array(6));
    for (let j = 0; j < 6; j++) {
      const h = j < 3 ? 1e-4 : 1e-7, qh = q.slice();
      qh[j] += h;
      const rh = residual(qh, s);
      for (let i = 0; i < 6; i++) J[i][j] = (rh[i] - r[i]) / h;
    }
    const dq = gauss(J, r.map(v => -v));
    for (let j = 0; j < 6; j++) q[j] += dq[j];
  }
  return q;
}
// Camber: negative = top of wheel inboard. Track change: sideways shift of the contact point, + = outward.
function angles(q) {
  const R = rotm(q.slice(3)), a = mul(R, [0, 1, 0]);
  return { camber: -Math.atan2(a[2], a[1]) * 180 / Math.PI, track: carrierPoint(q, [0, 0, -WHEEL_R], R)[1] - W0[1] };
}
// SOLVER END

// QUARTER-CAR START — one corner per axle, SI units, displacements from static equilibrium.
const QC = { ms: 450, mu: 65, ks: 30000, cs: 2000, kt: 200000, g: 9.81 };
QC.fStatic = (QC.ms + QC.mu) * QC.g;
const ROAD_PERIOD = 24;
function roadProfile(s) {
  s = ((s % ROAD_PERIOD) + ROAD_PERIOD) % ROAD_PERIOD;
  if (s > 4 && s < 4.5) return 0.02 * (1 - Math.cos(2 * Math.PI * (s - 4) / 0.5));
  if (s > 14 && s < 14.7) return -0.015 * (1 - Math.cos(2 * Math.PI * (s - 14) / 0.7));
  return 0;
}
function corner() { return { zs: 0, vs: 0, zu: 0, vu: 0, zr: 0, load: QC.fStatic }; }
function stepCorner(c, zr, dt) {
  const fs = QC.ks * (c.zs - c.zu) + QC.cs * (c.vs - c.vu);
  const ft = Math.max(QC.kt * (zr - c.zu), -QC.fStatic);
  c.vs += (-fs / QC.ms) * dt;
  c.vu += ((fs + ft) / QC.mu) * dt;
  c.zs += c.vs * dt; c.zu += c.vu * dt;
  c.zr = zr; c.load = QC.fStatic + ft;
}
// QUARTER-CAR END

// BLOWER START — clutch and boost model. Pedal 0..1; the clutch closes only in the last 2 % of travel.
const BLOWER = { ratio: 2.6, engageAt: 0.98, tauUp: 0.25, tauDown: 0.7, boostMax: 0.5, psAtmo: 115, psBoost: 180 };
function stepBlower(b, pedal, dt) {
  b.engaged = pedal >= BLOWER.engageAt;
  const target = b.engaged ? 1 : 0, tau = b.engaged ? BLOWER.tauUp : BLOWER.tauDown;
  b.spin += (target - b.spin) * (1 - Math.exp(-dt / tau));
  b.boost = BLOWER.boostMax * b.spin * b.spin;
  b.power = BLOWER.psAtmo + (BLOWER.psBoost - BLOWER.psAtmo) * b.spin * b.spin;
}
// BLOWER END
</script>

