[hidden] { display: none !important; }
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 15px; line-height: 1.55; }
a { color: var(--accent); }
.wrap {
  max-width: 1180px; margin: 0 auto; display: grid; gap: 24px;
  padding: max(20px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) max(48px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left));
}
.eyebrow { font-family: var(--mono); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--accent); }
h1 { font-family: var(--display); font-weight: 800; font-size: clamp(28px, 4.6vw, 42px); line-height: 1.05; margin: 6px 0 8px; text-wrap: balance; letter-spacing: -.01em; }
h2 { font-family: var(--display); font-weight: 700; font-size: 22px; margin: 0 0 12px; text-wrap: balance; }
.lede { max-width: 70ch; color: var(--muted); margin: 0; }
.crumbs, .pager { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px 16px; font-family: var(--mono); font-size: 12px; color: var(--muted); }
.crumbs a, .pager a { display: inline-flex; align-items: center; min-height: 44px; text-decoration: none; font-weight: 600; }

/* Buttons: 44 px targets, no double-tap zoom. */
button { font: 500 14px var(--body); color: var(--fg); background: transparent; border: 1px solid var(--rule); border-radius: 6px; padding: 8px 12px; min-height: 44px; cursor: pointer; touch-action: manipulation; }
button[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: var(--panel); }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.toolbar { display: flex; flex-wrap: wrap; gap: 12px 24px; align-items: center; }
.seg-group { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 8px; }
.seg { display: inline-flex; flex-wrap: wrap; border: 1px solid var(--rule); border-radius: 6px; overflow: hidden; background: var(--panel); }
.seg button { border: 0; border-radius: 0; }
.seg button + button { border-left: 1px solid var(--rule); }
.seg-label, .label { font-family: var(--mono); font-size: 11px; letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }

/* Viewer: stage keeps the museum photo's aspect so the overlay lines up; in phone landscape its height is capped to the
   viewport (width follows) so the page can still be scrolled past the touch-locked stage. */
.viewer { display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: 16px; align-items: start; }
@media (max-width: 860px) { .viewer { grid-template-columns: minmax(0, 1fr); } }
.stage {
  --ar: 1.4944; position: relative; background: var(--stage); border: 1px solid var(--rule); border-radius: 6px;
  aspect-ratio: var(--aspect, 1200 / 803); width: min(100%, calc((100svh - 32px) * var(--ar))); justify-self: center;
  overflow: hidden; touch-action: none; -webkit-user-select: none; user-select: none;
}
.stage img, .stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.stage img { filter: brightness(.72) saturate(.85); }
.stage .hint { position: absolute; left: 10px; bottom: 8px; font-family: var(--mono); font-size: 11px; color: var(--muted); pointer-events: none; }
.stage .credit { position: absolute; right: 8px; bottom: 6px; font-family: var(--mono); font-size: 10px; color: #f1f3f5; background: rgba(0,0,0,.55); padding: 2px 6px; border-radius: 3px; }
.stage .credit a { color: inherit; }
.stage .fail { position: absolute; inset: 0; margin: 0; padding: 16px; }
.side { display: grid; gap: 14px; align-content: start; min-width: 0; }
.panel { background: var(--panel); border: 1px solid var(--rule); border-radius: 6px; padding: 14px; display: grid; gap: 10px; min-width: 0; }
.readouts { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px 8px; }
.readouts div { display: grid; gap: 1px; }
.readouts output { font-family: var(--mono); font-size: 19px; font-variant-numeric: tabular-nums; }
.readouts small { font-family: var(--mono); font-size: 11px; color: var(--muted); }
.row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.slider { display: grid; gap: 4px; }
input[type=range] { width: 100%; min-height: 32px; accent-color: var(--accent); }
.trace svg, svg.diagram { width: 100%; height: auto; display: block; }
.trace text, svg.diagram text { font-family: var(--mono); font-size: 9px; fill: var(--muted); }
.key { display: flex; gap: 14px; flex-wrap: wrap; font-family: var(--mono); font-size: 11px; color: var(--muted); }
.key i { display: inline-block; width: 14px; height: 3px; vertical-align: middle; margin-right: 5px; }
.legend { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-size: 13px; }
.legend li { display: grid; grid-template-columns: 12px 1fr; gap: 10px; align-items: center; }
