.cyls { display: grid; grid-template-columns: repeat(var(--n, 4), 1fr); gap: 6px; }
.cyl { border: 1px solid var(--rule); border-radius: 4px; padding: 6px; display: grid; gap: 2px; text-align: center; }
.cyl b { font-family: var(--mono); font-size: 11px; color: var(--muted); font-weight: 500; }
