footer { display: grid; gap: 8px; font-size: 13px; color: var(--muted); border-top: 1px solid var(--rule); padding-top: 12px; }
footer summary { cursor: pointer; min-height: 32px; }
footer ul { margin: 4px 0 0; padding-left: 18px; }
.fail { color: var(--warn); }

