.stop a:hover { border-color: var(--accent); }
.stop b { font-family: var(--display); font-size: 17px; }
.stop small { font-family: var(--mono); font-size: 11px; color: var(--accent); }
.stop span { font-size: 14px; color: var(--muted); }

