      c.flame.position.copy(at(x, deck - 0.03, 0.9 * bR + 0.07)); c.flame.quaternion.copy(axisQ); group.add(c.flame);
      stage.onTheme(() => { tubeMat.color.copy(stage.color("--l1")); c.flame.material.color.copy(stage.color("--l2")); });
