  return {
    layout({ active }) { group.visible = active; },
    update(dt) {
      tPhoto += dt;
      if (playing) theta += dt * (rpm / 60) * 2 * Math.PI;
      pose();
      ui.set("crank", ((theta * 180 / Math.PI) % 720).toFixed(0));
      ui.set("cam", ((theta * 90 / Math.PI) % 360).toFixed(0));
    },
  };
}

