  }
  poseBlower(0); drawSvg();

  let frameN = 0;
  return {
    layout({ active }) { group.visible = active; },
    update(dt) {
      if (auto) { autoT += dt; pedal = autoPedal(autoT); ui.slider("pedal").set(Math.round(pedal * 100)); }
      poseBlower(dt);
      if (++frameN % 2 === 0) drawSvg();
      ui.set("pedal", Math.round(pedal * 100)); ui.set("rotor", (B.ratio * bl.spin).toFixed(1));
      ui.set("boost", bl.boost.toFixed(2)); ui.set("power", Math.round(bl.power));
      ui.badge("clutch").set(bl.engaged ? "Clutch engaged" : "Clutch open", bl.engaged);
      ui.meter("boost").set(bl.boost / B.boostMax, bl.spin > 0.5);
    },
  };
}

