// Valve train: cam lift, a spring-closed valve that can float, and a desmodromic (cam-closed) valve.
// Pure: no DOM, no three.js. Cam angle φ in rad (half crank speed); lift in m; all values illustrative.
const TAU = 2 * Math.PI;

// p = { lift (m), open (cam rad where the event starts), duration (cam rad) }. Cosine bump: smooth velocity, finite acceleration.
export function camLift(phi, p) {
  const u = (((phi - p.open) % TAU) + TAU) % TAU / p.duration;
  if (u <= 0 || u >= 1) return { L: 0, dL: 0, ddL: 0 };
  const w = TAU * u, k = Math.PI / p.duration;
  return { L: p.lift * (1 - Math.cos(w)) / 2, dL: p.lift * k * Math.sin(w), ddL: p.lift * 2 * k * k * Math.cos(w) };
}

// Spring rate that just keeps the valve on the cam nose at floatRpm (crank rpm). Max closing deceleration is at the nose,
// where the spring force k·(lift + preload) must match m·|L''|·ω².
export function springRateFor(p) {
  const w = p.floatRpm / 2 * TAU / 60, k = Math.PI / p.duration;
  return p.mass * p.lift * 2 * k * k * w * w / (p.lift + p.preload);
}

// Simulate a spring-closed valve on a pushing-only cam at crank speed rpm, in cam-angle steps (true physics at any
// display speed). Returns two-revolution-settled samples over one cam revolution: cam lift, valve lift, separation.
export function simulateSpringValve(p, rpm, samples = 360) {
  const k = p.k ?? springRateFor(p), w = rpm / 2 * TAU / 60, dphi = 0.002, dt = dphi / w;
  let x = 0, v = 0, maxSep = 0;
  const out = { phi: [], cam: [], valve: [], maxSep: 0 };
  const total = 2 * TAU, every = TAU / samples;
  let next = TAU;
  for (let phi = 0; phi < total; phi += dphi) {
    const c = camLift(phi, p);
    v += (-k * (x + p.preload) / p.mass) * dt;   // spring pushes the valve shut
    x += v * dt;
    if (x <= c.L) { x = c.L; v = Math.max(v, c.dL * w); }   // cam can push, never pull
    if (phi >= TAU) {
      maxSep = Math.max(maxSep, x - c.L);
      if (phi >= next) { out.phi.push(phi - TAU); out.cam.push(c.L); out.valve.push(x); next += every; }
    }
  }
  out.maxSep = maxSep;
  return out;
}

// Desmodromic: the opening cam pushes the valve open through one rocker, a conjugate closing cam pulls it shut through
// another. Conjugate means open radius + close radius = constant, so the valve position is exactly L(φ) at any speed.
export function desmoCams(phi, p) {
  const { L } = camLift(phi, p);
  return { open: p.base + L, close: p.base + p.lift - L, valve: L };
}
// Front steering geometry, top view. Pure: no DOM, no three.js.
// Frame in mm: x forward, y left; front axle at x = 0, rear axle at x = −wheelbase. Steer angle δ in rad, + = turning left.
const hyp = Math.hypot;
const rot = ([x, y], a) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a)];

// Double-pivot (stub-axle) steering with a trapezoid linkage: kingpins at (0, ±k), steering arms of length a pointing
// rearwards and inwards by β, joined by one tie rod. β = atan(k / wheelbase) aims both arms at the rear-axle centre,
// the classic condition for the wheel axes to meet near one point (Ackermann).
export function createDoublePivot({ kingpinHalf: k, arm: a, wheelbase: wb, armAngle }) {
  const beta = armAngle ?? Math.atan(k / wb);
  const KL = [0, k], KR = [0, -k];
  const armVec = (side, d) => rot([-a * Math.cos(beta), -side * a * Math.sin(beta)], d);
  const end = (K, side, d) => { const v = armVec(side, d); return [K[0] + v[0], K[1] + v[1]]; };
  const tie = hyp(...[0, 1].map(i => end(KL, 1, 0)[i] - end(KR, -1, 0)[i]));

  // Given the left wheel's angle (driven by the steering column), close the tie rod for the right wheel.
  function solve(dL) {
    const PL = end(KL, 1, dL);
    const dx = PL[0] - KR[0], dy = PL[1] - KR[1], d = hyp(dx, dy);
    const along = (a * a - tie * tie + d * d) / (2 * d), h = Math.sqrt(Math.max(0, a * a - along * along));
    const mx = KR[0] + along * dx / d, my = KR[1] + along * dy / d;
    const cands = [[mx + h * dy / d, my - h * dx / d], [mx - h * dy / d, my + h * dx / d]];
    const guess = end(KR, -1, dL);
    const PR = cands.reduce((best, c) => (hyp(c[0] - guess[0], c[1] - guess[1]) < hyp(best[0] - guess[0], best[1] - guess[1]) ? c : best));
    const v0 = armVec(-1, 0), v = [PR[0] - KR[0], PR[1] - KR[1]];
    const raw = Math.atan2(v[1], v[0]) - Math.atan2(v0[1], v0[0]);
    const dR = Math.atan2(Math.sin(raw), Math.cos(raw));   // wrap to (−π, π]
    return { dL, dR, PL, PR, KL, KR, ...turning(dL, dR) };
  }

  // Each front wheel's axis meets the rear-axle line at y = ±k + wb / tan δ. Equal y's = no tyre scrub.
  function turning(dL, dR) {
    if (Math.abs(dL) < 1e-6 || Math.abs(dR) < 1e-6) return { icrL: Infinity, icrR: Infinity, radius: Infinity, idealOuter: 0 };
    const icrL = k + wb / Math.tan(dL), icrR = -k + wb / Math.tan(dR);
    const inner = Math.max(Math.abs(dL), Math.abs(dR));
    const idealOuter = Math.sign(dL) * Math.atan(1 / (1 / Math.tan(inner) + 2 * k / wb));
    const icrY = (icrL + icrR) / 2, outerK = dL > 0 ? KR : KL;
    return { icrL, icrR, idealOuter, radius: hyp(-wb - outerK[0], icrY - outerK[1]) };
  }

  return { k, a, wb, beta, tie, solve, armVec };
}

// The older centre-pivot (turntable) axle: the whole beam swings about its middle. The wheel axes always meet,
// but the front support narrows (k·cos δ) and the inner wheel swings back by k·sin δ, toward the body.
export function centrePivot({ kingpinHalf: k, wheelbase: wb }, d) {
  const L = rot([0, k], d), R = rot([0, -k], d);
  const straight = Math.abs(d) < 1e-6;
  const icrY = straight ? Infinity : wb / Math.tan(d), outer = d > 0 ? R : L;
  return { L, R, halfTrack: k * Math.cos(d), swingBack: k * Math.abs(Math.sin(d)), icrY, radius: straight ? Infinity : hyp(outer[0] + wb, outer[1] - icrY) };
}
export function helix(a, b, turns = 7, r = 0.046, wire = 0.007) {
  const d = new THREE.Vector3().subVectors(b, a), len = d.length(), n = d.clone().normalize();
  const t1 = V(1, 0, 0).cross(n).normalize(), t2 = n.clone().cross(t1), pts = [];
  for (let i = 0; i <= 200; i++) {
    const u = i / 200, th = u * Math.PI * 2 * turns;
    pts.push(a.clone().addScaledVector(n, u * len).addScaledVector(t1, Math.cos(th) * r).addScaledVector(t2, Math.sin(th) * r));
  }
  return new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 200, wire, 6, false);
}

// Tyre (torus) with its axis along y. R = ring radius, r = section radius (m).
export function spokedWheel(tyreMat, spokeMat, R = 0.42, spokes = 12) {
  const g = tyre(tyreMat, R, 0.022);
  for (let i = 0; i < spokes; i++) { const a = i / spokes * Math.PI * 2; g.add(place(rod(spokeMat, 0.012), V(0, 0, 0), V(R * Math.cos(a), 0, R * Math.sin(a)))); }
  g.add(place(rod(spokeMat, 0.05), V(0, -0.06, 0), V(0, 0.06, 0)));
  return g;
}

